SELECT l.entity_kind || ' ' || l.entity_name || ' → ' || l.target_path AS detail FROM project_document_links l WHERE l.project_id = $1 AND l.target_kind = '' AND l.target_path !~ '^[a-z][a-z0-9+.-]*://' AND NOT EXISTS (SELECT 1 FROM project_documents d WHERE d.project_id = l.project_id AND d.entity_kind = split_part(l.target_path, ':', 1) AND (d.entity_name = split_part(l.target_path, ':', 2) OR (d.entity_name = '' AND split_part(l.target_path, ':', 2) = ''))) ORDER BY 1
